import{_ as i,C as a,o as r,c as n,E as o,a2 as d}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"延迟 Agent 环境需要稳定身份，而不是替换式 Provisioning","description":"","frontmatter":{"title":"延迟 Agent 环境需要稳定身份，而不是替换式 Provisioning","date":"2026-08-07","column":"open-source-engineering","category":"daily","summary":"延迟环境的关键不是不断 upsert 新对象，而是在同一逻辑身份上显式报告 Pending、Ready、Failed，并让 materialize 与 report 收敛到同一生命周期对象；进程内幂等仍不等于重启后耐久或分布式 exactly-once。","item_id":"Q-20260807-03","source_research_object":"research/analysis/Q-20260807-03-stable-identity-provisioning-gate.md","source_reading_result":"research/reading/Q-20260807-03-deferred-environment-provisioning.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-07-stable-identity-provisioning-gate-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-07-stable-identity-provisioning-gate.md","filePath":"zh/engineering/2026-08-07-stable-identity-provisioning-gate.md","lastUpdated":1787407830000}'),l={name:"zh/engineering/2026-08-07-stable-identity-provisioning-gate.md"};function s(c,e,p,g,u,m){const t=a("ArticleCover");return r(),n("div",null,[o(t,{image:"/assets/covers/daily-2026-08-07-stable-identity-provisioning-gate-cover-v2.jpg",kicker:"开源工程 · 每日研究",title:"延迟 Agent 环境需要稳定身份，而不是替换式 Provisioning",summary:"延迟环境的关键不是不断 upsert 新对象，而是在同一逻辑身份上显式报告 Pending、Ready、Failed，并让 materialize 与 report 收敛到同一生命周期对象；进程内幂等仍不等于重启后耐久或分布式 exactly-once。",version:"Q-20260807-03",status:"Daily Runtime V5 · 2026-08-07",languageHref:"/en/engineering/2026-08-07-stable-identity-provisioning-gate",languageLabel:"English"}),e[0]||(e[0]=d(' # 延迟 Agent 环境需要稳定身份，而不是替换式 Provisioning <p>Agent Runtime 越来越常见一种资源：现在还不能使用，但任务已经需要引用它。远程 sandbox、browser environment、workspace、tool container 都可能先进入 Pending，稍后才变成 Ready 或 Failed。</p><p>这种情况下，最危险的 API 设计不是“等待时间太长”，而是<strong>生命周期变化时不断替换资源对象</strong>。一旦 identity 被替换，排队中的任务、UI 投影、引用关系和审计日志就要追逐一个新对象，race 与状态漂移随之增加。</p><p>同日完成的 Research Object 给出的核心模式是：稳定 identity + 显式 report-and-materialize lifecycle。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p><strong>Provisioning state 应该变化，资源 identity 不应该跟着变化。</strong></p><p>Pending、Ready、Failed 是同一个逻辑资源的生命周期类。<code>report</code> 负责提交状态，<code>materialize</code> 负责建立或取得对应的 provisioned object；两者无论谁先到，都应收敛到同一个 identity，而不是靠 replacement/upsert 把旧对象覆盖掉。</p><p>这套本地幂等语义很有价值，但也必须守住边界：进程内 stable identity 和 lock-protected state 不能被宣传成 crash durability、multi-process consensus 或 exactly-once external provisioning。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文只消费 <code>Q-20260807-03</code> 的 Production-authorized Research Object。Production 没有从 Signal Pool 或 Reading Result 重新研究，也没有引入新的外部事实。Reading Result 仅作为 Research Object 声明的证据边界和来源追溯入口。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>Research Object 保留了五个关键机制。</p><p>第一，deferred environment 的状态操作被收敛成两个 manager-level surface：provisioning-status reporting 与 explicit materialization。这样 caller 不需要分别维护多个 upsert 路径。</p><p>第二，report-first 与 materialize-first 都指向同一个 stable provisioned environment identity。Pending、Ready 或 Failed 更新不会更换被其他任务引用的逻辑对象。</p><p>第三，ordinary environment 与 provisioned environment 被明确分开。对普通环境发送 provisioning report 会以 <code>Ok(None)</code> 被忽略；而对普通环境执行 materialization 会返回 typed <code>ProvisioningModeConflict</code>，并保留原对象。这种不对称语义可以合理，但如果 Runtime 没有 audit surface，<code>Ok(None)</code> 很容易被调用者误读成“状态已经接受”。</p><p>第四，terminal lifecycle class 是 sticky 的：Ready 与 Failed 不能互相翻转，重复的同类 terminal report 可以幂等处理。不过 Ready 内部 payload 仍可以更新，因此“Ready 幂等”并不等于“整个 Ready 记录永久不可变”。</p><p>第五，移除 registration-handle Drop 自动写 Failed 后，生命周期变得更显式，但也失去了一个隐式 abandonment signal。系统必须把 timeout、disappeared worker 和 terminal failure 的所有权交给明确的上层组件。</p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设计</th><th>Identity</th><th>生命周期更新</th><th>冲突处理</th><th>恢复能力</th></tr></thead><tbody><tr><td>Replacement / upsert</td><td>状态变化可能换对象</td><td>caller 分散更新</td><td>容易被覆盖语义吞掉</td><td>引用与任务需追逐新对象</td></tr><tr><td>Stable identity + report/materialize</td><td>单一逻辑 resource ID</td><td>Pending / Ready / Failed 显式报告</td><td>typed mode conflict；部分 report 可忽略</td><td>进程内顺序与 race 更可控</td></tr><tr><td>Durable production extension</td><td>Stable resource ID + persistent event/receipt</td><td>本地状态之外有持久事件与 effect receipt</td><td>conflict 与 ignored report 都可审计</td><td>可在重启后对账，仍需外部幂等</td></tr></tbody></table><p>前两行来自 Research Object 的机制分析；第三行是 Research Center 对生产 Runtime 的工程扩展建议，不表示所分析实现已经提供重启耐久或 exactly-once 保证。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>这类 Provisioning API 的价值在于把四件事拆开：<strong>资源 identity、lifecycle class、readiness payload，以及 connection/use activation。</strong></p><p>identity 应稳定，因为任务和 UI 都需要一个不会随状态变化而漂移的引用点。lifecycle class 应显式，因为 Pending、Ready、Failed 是不同控制意义。readiness payload 可以有版本，因为 Ready 后能力根、endpoint 或 metadata 仍可能被补充。connection/use 则应再次单独建模，因为“环境已经 Ready”并不等于“某个任务已经连接并开始使用”。</p><p>report/materialize 的顺序无关性也很重要。一个 status report 可能先于显式 Pending 对象到达；只要最终能收敛到同一个 identity，caller 就不需要靠重试顺序制造正确性。</p><p>但 local idempotence 不能替代 distributed durability。进程退出后，如果没有持久 event、receipt 或 external idempotency key，Runtime 仍然不知道某次 provisioning side effect 是否已经发生。此时“再次 materialize”可能创建第二个真实资源，而内存 manager 自己无法证明 exactly-once。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对数字员工，remote browser、sandbox、workspace 或 tool environment 应拥有独立的 durable logical resource ID。Provisioning completion 与 connection/use start 应是两个可观察 transition，避免 Ready 自动等于 Active。</p><p>Runtime 需要一个明确 owner 负责 timeout 与 abandonment。既然 Drop 不再自动把消失的 registration 解释成 Failed，那么 owner 必须周期性判断 Pending 是否已经失去执行主体，并产生显式 terminal verdict。</p><p>对 CodeFlowMu，worker/tool-environment provisioning 更适合统一成 report-and-materialize API，而不是多个 caller 各自 replacement/upsert。FCoP/Runtime 层可以在 manager 之上增加 append-only provisioning event、effect receipt 与 recovery reconciliation。对 ordinary environment 的 ignored report 也应至少产生可观测 diagnostic，使 operator 能区分 benign late report 与 caller bug。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>当前证据只建立进程内 manager 语义与回归测试。它没有证明 restart recovery、multi-process race、remote connection 成功、fleet-level reliability 或外部副作用的 exactly-once。</p><p><code>Ok(None)</code> 的 ignored report 可能隐藏调用错误；移除 Drop-based failure 后 Pending 可能长期无人负责；Ready payload 在 Ready 类内仍可变化；被移除 API 的下游兼容性也没有由当前对象证明。</p><p>因此，可辩护的结论是“稳定 identity 与显式 lifecycle 能减少本地歧义”，而不是“该实现已经解决分布式 Provisioning”。</p><h2 id="未来工作" tabindex="-1">未来工作 <a class="header-anchor" href="#未来工作" aria-label="Permalink to &quot;未来工作&quot;">​</a></h2><p>下一步应明确四个问题：谁拥有 timeout 与 terminal failure；ignored report 是否必须生成 audit event 以及 severity 如何划分；重启后需要怎样的持久 event/receipt 才能恢复 Pending/Ready/Failed 而不重复外部副作用；Ready payload 中哪些字段应该在什么时点冻结或版本化。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图以一个 Stable Resource ID 为中心，展示 report-first/materialize-first 收敛到 Pending/Ready/Failed，并将 Connection/Use 与 Provisioning lifecycle 分开；下方 durable event/receipt layer 明确标注为生产扩展建议，而非来源已证明能力。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260807-03-stable-identity-provisioning-gate.md" target="_blank" rel="noreferrer">Research Object — Stable-Identity Provisioning Gate</a>：本文唯一分析输入，包含生命周期语义、不确定性、反证与工程影响。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260807-03-deferred-environment-provisioning.md" target="_blank" rel="noreferrer">Reading Result — Deferred environment provisioning</a>：Research Object 声明的证据边界与来源追溯记录；Production 未从该文件重新开展分析。</li></ol>',39))])}const b=i(l,[["render",s]]);export{y as __pageData,b as default};
